CREATE TYPE "UserRole" AS ENUM ('SUPER_ADMIN','ADMIN','SECRETARY','FINANCE','TRIAGE','CONTRACTS','SOCIAL_SERVICE','RECEPTION','COMMERCIAL','HR','STUDENT','PROFESSOR','COMPANY','INTERNSHIP_SUPERVISOR');
CREATE TYPE "PasswordAlgorithm" AS ENUM ('ARGON2ID','LEGACY_MD5');
CREATE TYPE "RecordStatus" AS ENUM ('ACTIVE','INACTIVE','PENDING','ARCHIVED');
CREATE TYPE "ContractStatus" AS ENUM ('DRAFT','PENDING_SIGNATURE','ACTIVE','SUSPENDED','TERMINATED','CANCELLED');
CREATE TYPE "RequestStatus" AS ENUM ('OPEN','IN_PROGRESS','WAITING','DONE','CANCELLED');

CREATE TABLE "Person" ("id" TEXT PRIMARY KEY, "fullName" TEXT NOT NULL, "socialName" TEXT, "cpf" TEXT UNIQUE, "rg" TEXT, "birthDate" TIMESTAMP(3), "sex" TEXT, "email" TEXT, "phone" TEXT, "secondaryPhone" TEXT, "zipCode" TEXT, "address" TEXT, "addressNumber" TEXT, "addressExtra" TEXT, "district" TEXT, "city" TEXT, "state" TEXT, "motherName" TEXT, "fatherName" TEXT, "legalGuardian" TEXT, "guardianCpf" TEXT, "guardianEmail" TEXT, "status" "RecordStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Company" ("id" TEXT PRIMARY KEY, "cnpj" TEXT UNIQUE, "legalName" TEXT NOT NULL, "tradeName" TEXT, "email" TEXT, "financeEmail" TEXT, "phone" TEXT, "zipCode" TEXT, "address" TEXT, "addressNumber" TEXT, "district" TEXT, "city" TEXT, "state" TEXT, "legalRep" TEXT, "status" "RecordStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "email" TEXT NOT NULL UNIQUE, "login" TEXT UNIQUE, "passwordHash" TEXT NOT NULL, "passwordAlgorithm" "PasswordAlgorithm" NOT NULL DEFAULT 'ARGON2ID', "role" "UserRole" NOT NULL DEFAULT 'ADMIN', "active" BOOLEAN NOT NULL DEFAULT true, "legacySource" TEXT, "legacyId" TEXT, "personId" TEXT REFERENCES "Person"("id") ON DELETE SET NULL, "companyId" TEXT REFERENCES "Company"("id") ON DELETE SET NULL, "lastLoginAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "User_legacySource_legacyId_idx" ON "User"("legacySource","legacyId");

CREATE TABLE "Course" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "code" TEXT, "modality" TEXT, "workload" INTEGER, "status" "RecordStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ClassGroup" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "code" TEXT, "type" TEXT, "courseId" TEXT REFERENCES "Course"("id") ON DELETE SET NULL, "unit" TEXT, "room" TEXT, "startDate" TIMESTAMP(3), "endDate" TIMESTAMP(3), "status" "RecordStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Contract" ("id" TEXT PRIMARY KEY, "number" TEXT, "personId" TEXT NOT NULL REFERENCES "Person"("id") ON DELETE RESTRICT, "companyId" TEXT REFERENCES "Company"("id") ON DELETE SET NULL, "courseId" TEXT REFERENCES "Course"("id") ON DELETE SET NULL, "type" TEXT, "status" "ContractStatus" NOT NULL DEFAULT 'DRAFT', "startDate" TIMESTAMP(3), "endDate" TIMESTAMP(3), "suspensionStart" TIMESTAMP(3), "suspensionEnd" TIMESTAMP(3), "terminationDate" TIMESTAMP(3), "monthlyValue" DECIMAL(12,2), "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Enrollment" ("id" TEXT PRIMARY KEY, "personId" TEXT NOT NULL REFERENCES "Person"("id") ON DELETE RESTRICT, "courseId" TEXT REFERENCES "Course"("id") ON DELETE SET NULL, "classGroupId" TEXT REFERENCES "ClassGroup"("id") ON DELETE SET NULL, "companyId" TEXT REFERENCES "Company"("id") ON DELETE SET NULL, "contractId" TEXT REFERENCES "Contract"("id") ON DELETE SET NULL, "startDate" TIMESTAMP(3), "endDate" TIMESTAMP(3), "status" "RecordStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Enrollment_personId_classGroupId_idx" ON "Enrollment"("personId","classGroupId");
CREATE TABLE "Attendance" ("id" TEXT PRIMARY KEY, "personId" TEXT NOT NULL REFERENCES "Person"("id") ON DELETE RESTRICT, "classGroupId" TEXT NOT NULL REFERENCES "ClassGroup"("id") ON DELETE RESTRICT, "classDate" TIMESTAMP(3) NOT NULL, "present" BOOLEAN NOT NULL DEFAULT false, "justified" BOOLEAN NOT NULL DEFAULT false, "reason" TEXT, "attachment" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("personId","classGroupId","classDate"));
CREATE TABLE "Grade" ("id" TEXT PRIMARY KEY, "personId" TEXT NOT NULL REFERENCES "Person"("id") ON DELETE RESTRICT, "classGroupId" TEXT NOT NULL REFERENCES "ClassGroup"("id") ON DELETE RESTRICT, "label" TEXT NOT NULL, "value" DECIMAL(10,2) NOT NULL, "maxValue" DECIMAL(10,2), "date" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Internship" ("id" TEXT PRIMARY KEY, "contractId" TEXT NOT NULL REFERENCES "Contract"("id") ON DELETE RESTRICT, "institution" TEXT, "supervisorName" TEXT, "supervisorEmail" TEXT, "courseName" TEXT, "semester" TEXT, "weeklyHours" INTEGER, "startTime" TEXT, "endTime" TEXT, "insurancePolicy" TEXT, "status" "RecordStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Vacancy" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id") ON DELETE RESTRICT, "title" TEXT NOT NULL, "profile" TEXT, "area" TEXT, "activities" TEXT, "city" TEXT, "district" TEXT, "minAge" INTEGER, "maxAge" INTEGER, "quantity" INTEGER NOT NULL DEFAULT 1, "scholarship" DECIMAL(12,2), "expiresAt" TIMESTAMP(3), "status" "RecordStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Application" ("id" TEXT PRIMARY KEY, "vacancyId" TEXT NOT NULL REFERENCES "Vacancy"("id") ON DELETE RESTRICT, "personId" TEXT NOT NULL REFERENCES "Person"("id") ON DELETE RESTRICT, "status" "RequestStatus" NOT NULL DEFAULT 'OPEN', "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("vacancyId","personId"));
CREATE TABLE "FinancialTitle" ("id" TEXT PRIMARY KEY, "companyId" TEXT REFERENCES "Company"("id") ON DELETE SET NULL, "contractId" TEXT REFERENCES "Contract"("id") ON DELETE SET NULL, "description" TEXT NOT NULL, "competence" TEXT, "dueDate" TIMESTAMP(3) NOT NULL, "amount" DECIMAL(12,2) NOT NULL, "status" "RequestStatus" NOT NULL DEFAULT 'OPEN', "bankRef" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Payment" ("id" TEXT PRIMARY KEY, "financialTitleId" TEXT NOT NULL REFERENCES "FinancialTitle"("id") ON DELETE RESTRICT, "paidAt" TIMESTAMP(3) NOT NULL, "amount" DECIMAL(12,2) NOT NULL, "externalRef" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ServiceRequest" ("id" TEXT PRIMARY KEY, "personId" TEXT REFERENCES "Person"("id") ON DELETE SET NULL, "type" TEXT NOT NULL, "description" TEXT, "response" TEXT, "dueDate" TIMESTAMP(3), "status" "RequestStatus" NOT NULL DEFAULT 'OPEN', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Document" ("id" TEXT PRIMARY KEY, "personId" TEXT REFERENCES "Person"("id") ON DELETE SET NULL, "contractId" TEXT REFERENCES "Contract"("id") ON DELETE SET NULL, "type" TEXT NOT NULL, "fileName" TEXT NOT NULL, "storageKey" TEXT NOT NULL, "mimeType" TEXT, "checksum" TEXT, "version" INTEGER NOT NULL DEFAULT 1, "status" "RecordStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "LegacyMapping" ("id" TEXT PRIMARY KEY, "source" TEXT NOT NULL, "entity" TEXT NOT NULL, "legacyId" TEXT NOT NULL, "newId" TEXT NOT NULL, "fingerprint" TEXT, "syncedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("source","entity","legacyId"));
CREATE INDEX "LegacyMapping_entity_newId_idx" ON "LegacyMapping"("entity","newId");
CREATE TABLE "SyncRun" ("id" TEXT PRIMARY KEY, "source" TEXT NOT NULL, "entity" TEXT, "mode" TEXT NOT NULL, "status" TEXT NOT NULL, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "finishedAt" TIMESTAMP(3), "readCount" INTEGER NOT NULL DEFAULT 0, "writeCount" INTEGER NOT NULL DEFAULT 0, "errorCount" INTEGER NOT NULL DEFAULT 0, "message" TEXT);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY, "userId" TEXT REFERENCES "User"("id") ON DELETE SET NULL, "action" TEXT NOT NULL, "entity" TEXT, "entityId" TEXT, "metadata" JSONB, "ip" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "AuditLog_entity_entityId_idx" ON "AuditLog"("entity","entityId");
CREATE INDEX "AuditLog_createdAt_idx" ON "AuditLog"("createdAt");
